package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamPracticalCritBank4 {
    private const val T = "දෘෂ්ටිකෝණ, මානව ව්‍යුහය, ප්‍රායෝගික මාධ්‍ය හා විචාරය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ලිනෝ කට් (Linocut) හෝ ලී කුට්ටි මුද්‍රණයේදී කැටයම් පිහියෙන් කපා ඉවත් කරනු ලබන කොටස් මුද්‍රිත කඩදාසියේ පෙනෙන්නේ කෙසේද?", "තීන්ත නොවැදී කඩදාසියේ සුදු පැහැයෙන්", "ඉතා තද කළු හා ඝන රේඛා ලෙස", "රන්වන් ලෝහමය පැහැයෙන්", "දම් පැහැති සෙවණැලි ලෙස", "උන්නත මුද්‍රණයේදී (Relief) තීන්ත තැවරෙන්නේ කපා ඉතිරි කළ උස් කොටස්වල පමණි."),
        q("ලිනෝ හෝ ලී කුට්ටි මුද්‍රණයක මතුපිට පෘෂ්ඨය මත මුද්‍රණ තීන්ත සමානව ආලේප කිරීමට භාවිත කරන රබර් රෝලරය කුමක්ද?", "බ්‍රේයර් රෝලරය (Brayer)", "ටියැන්ටින් නළය (Tjanting)", "පැලට් පිහිය (Palette Knife)", "සකපෝරු රෝදය (Potter's Wheel)", "තීන්ත පුවරුව මත බ්‍රේයර් රෝලරය රෝල් කර පසුව ලිනෝ තලය මත තුනී ස්තරයක් ආලේප කෙරේ."),
        q("මුද්‍රණ කලාවේදී තීන්ත ගෑ ලිනෝ කුට්ටිය මත තැබූ කඩදාසිය පිටුපසින් තදින් අතුල්ලා මුද්‍රණය ලබා ගැනීමට භාවිත කරන උපකරණය කුමක්ද?", "බැරන් උපකරණය (Baren)", "ස්ථායීකාරක ඉසිනය (Fixative)", "කැටයම් නියන (Gouge)", "ලෝහ මිටිය (Mallet)", "සාම්ප්‍රදායික ජපන් බැරන් උපකරණයක් හෝ සිනිඳු ලී හැන්දක් මුද්‍රණ යන්ත්‍රයක් නොමැති විට භාවිත කළ හැකිය."),
        q("තඹ හෝ සින්ක් තහඩුවක ඇසිඩ් යොදා හෝ තියුණු තුඩකින් කාණු කපා ඒ කාණු ඇතුළේ තීන්ත රඳවා මුද්‍රණය කරන ශිල්පය කුමක්ද?", "ඉන්ටැග්ලියෝ මුද්‍රණය (Intaglio / Etching)", "උන්නත කැටයම් මුද්‍රණය (Relief Print)", "සිල්ක් ස්ක්‍රීන් මුද්‍රණය (Silk Screen)", "ස්ටෙන්සිල් මුද්‍රණය (Stencil Print)", "උන්නත මුද්‍රණයට ප්‍රතිවිරුද්ධව මෙහිදී තීන්ත රැඳෙන්නේ කපන ලද ගැඹුරු රේඛා තුළය."),
        q("තෙල් සහ ජලය එකිනෙක විකර්ෂණය වන රසායනික මූලධර්මය මත පදනම්ව හුණුගල් පුවරුවකින් සිදුකරන මුද්‍රණ ක්‍රමය කුමක්ද?", "ලිතොග්‍රැෆි මුද්‍රණය (Lithography)", "වුඩ්කට් මුද්‍රණය (Woodcut)", "එන්ග්‍රේවින් මුද්‍රණය (Engraving)", "ටයි-ඩයි මුද්‍රණය (Tie-Dye)", "තෙල්මය පැන්සලකින් ගල් පුවරුව මත ඇඳ ජලය තෙමා මුද්‍රණ තීන්ත ආලේප කිරීම ලිතොග්‍රැෆි ක්‍රමයයි."),
        q("වීදුරු හෝ ඇක්‍රිලික් පුවරුවක් මත තීන්තයෙන් ඇඳ එය කඩදාසියට තද කර තනි අද්විතීය පිටපතක් පමණක් ගන්නා මුද්‍රණ ක්‍රමය කුමක්ද?", "මොනොප්‍රින්ට් (Monoprint / Monotype)", "ලිනෝකට් බහු මුද්‍රණය", "සිල්ක් ස්ක්‍රීන් කර්මාන්තය", "ඕෆ්සෙට් මුද්‍රණය", "'තනි මුද්‍රණය' යන අරුත ඇති මෙම ක්‍රමයෙන් ලැබෙන මුද්‍රිත පිටපත නැවත එලෙසම ලබාගත නොහැකිය."),
        q("ඝන කාඩ්බෝඩ් පුවරුවක් මත නූල්, රෙදි, කොළ හා වැලි වැනි ද්‍රව්‍ය අලවා වයන තලයක් සකසා මුද්‍රණය ගැනීමේ ක්‍රමය කුමක්ද?", "කොලාග්‍රාෆ් මුද්‍රණය (Collagraph)", "ලිතොග්‍රැෆි මුද්‍රණය (Lithography)", "ඇසිඩ් එචින් ක්‍රමය (Acid Etching)", "ෆොටෝග්‍රෑම් ක්‍රමය (Photogram)", "කොලාජ් නිර්මාණයක් මුද්‍රණ පුවරුවක් ලෙස යොදා ගැනීමෙන් විචිත්‍ර වයන මුද්‍රණ ලැබේ."),
        q("පාසල් පන්ති කාමරයේදී මෝස්තර මුද්‍රණයක් පහසුවෙන් අත්හදා බැලීමට කපා සකසා ගත හැකි ස්වාභාවික මුද්‍රා මාධ්‍ය මොනවාද?", "අල, කැරට් හෝ ගස්ලබු නටු කැබලි", "ඝන කිරිගරුඬ හා කළුගල් කුට්ටි", "උණු කළ යකඩ හා තඹ තහඩු", "වීදුරු කුඩු හා සිමෙන්ති පුවරු", "මෘදු එළවළු හා ශාක කොටස් කපා පෝස්ටර් වර්ණ තවරා පුනරාවර්තන රටා මුද්‍රණය ඉගෙන ගත හැකිය."),
        q("ශ්‍රී ලංකාවේ මාතලේ හපුවිද ප්‍රදේශයේ පාරම්පරික 'ලාක්ෂා කර්මාන්තයේ'දී (Lacquer Craft) භාවිත කරන ස්වාභාවික ලාකඩ ලබා ගන්නේ කුමකින්ද?", "කැප්පෙටියා වැනි ගස්වල ලාකඩ කෘමීන්ගේ ස්‍රාවයෙන්", "පොල් තෙල් හා හුණු කුඩු මිශ්‍ර කිරීමෙන්", "කිරිගරුඬ ගල් කුඩු උණු කිරීමෙන්", "රබර් කිරි සහ ප්ලාස්ටික් දිය කිරීමෙන්", "කැප්පෙටියා අතු මත ලාකඩ කෘමියා විසින් සාදන ලක් කඩ පිරිසිදු කර ස්වාභාවික වර්ණ මිශ්‍ර කර ලාක්ෂා සැකසේ."),
        q("දේශීය ලාක්ෂා කර්මාන්තයේදී සේසත් මිටි හා කෝටු වැනි දිගු භාණ්ඩ හැඩගැන්වීමේදී ඉටි කෙඳි නියපොත්තෙන් කඩා තබන සැරසිලි ක්‍රමය කුමක්ද?", "නියපොතු වැඩ (Niyapothu Weda)", "පට්ටල වැඩ (Patala Weda)", "ගල්බිංදු වැඩ (Galbindu)", "සකපෝරු වැඩ (Wheel Work)", "ලී මතුපිට කරකවා ගාන පට්ටල වැඩ ක්‍රමයට වඩා නියපොතු වැඩ ඉතා සියුම් අත් වැඩ රටා මවයි."),
        q("මහනුවර තලාතුඔය ආශ්‍රිත කලාසිරිගම හා හේනවල ප්‍රදේශවල ප්‍රකට 'දුම්බර රටා රෙදි විවීම' සඳහා භාවිත කළ සාම්ප්‍රදායික කෙඳි වර්ගය කුමක්ද?", "හණ කෙඳි (Hemp fibers)", "නයිලෝන් ප්ලාස්ටික් නූල්", "ලෝහ තඹ කම්බි", "රේන්ද සේද කෙඳි", "හණ පත්‍රවලින් ගත් ස්වාභාවික කෙඳි වර්ණ ගන්වා කුරුල්ලන් හා ජ්‍යාමිතික රටා බිත්ති සැරසිලි හා මලු ලෙස වියයි."),
        q("ශ්‍රී ලංකාවේ දකුණු පළාතේ ගාල්ල හා වැලිගම ප්‍රදේශ ආශ්‍රිතව ප්‍රචලිත වූ සියුම් අත්කම් රේන්ද කලාව කුමක්ද?", "බීරළු රේන්ද (Beeralu Bobbin Lace)", "ලාක්ෂා ලී කැටයම්", "අම්බලන්ගොඩ කෝලම් වෙස්මුහුණු", "කැලණි මැටි පිළිම කලාව", "කුඩා ලී බීරළු (Bobbins) සහ ඇල්පෙනිති කොට්ටයක් භාවිත කර නූල් ගොතා මෙම අලංකාර රේන්ද නිමවයි."),
        q("මහනුවර පිළිමතලාව හා ගඩලාදෙණිය ආශ්‍රිත පාරම්පරික 'පිත්තල කර්මාන්තයේදී' කුහර පහන් හා බඳුන් නිමවන ක්‍රම දෙක මොනවාද?", "වාත්තු ක්‍රමය හා තැළුම් ක්‍රමය", "සකපෝරු ක්‍රමය හා ඩයි ක්‍රමය", "ෆ්‍රොටාජ් ක්‍රමය හා කොලාජ් ක්‍රමය", "බතික් ක්‍රමය හා ස්ටෙන්සිල් ක්‍රමය", "මී ඉටි අච්චු යොදා ලෝහ උණු කර වත් කිරීම හා පිත්තල තහඩු තළා කැටයම් කිරීම දේශීය ක්‍රම වේ."),
        q("ශ්‍රී ලංකාවේ පන් පැදුරු හා කූඩා විවීමේදී (Mat Weaving) පන් ගස්වලට අලංකාර රතු, කළු හා කහ වර්ණ ලබා දීමට යොදා ගන්නේ මොනවාද?", "පතඟි, කහ හා ස්වාභාවික ශාක සායම්", "තෙල් සායම් හා වාර්නිෂ් තීන්ත", "මුද්‍රණාල තීන්ත හා ටර්පන්ටයින්", "ප්ලාස්ටික් ආලේපන කුඩු", "ගල්ලැහැ, වැටකේ හා හණ පන් ස්වාභාවික ශාක පොතු සමඟ තම්බා වර්ණ ගන්වා සාම්ප්‍රදායික රටා වියනු ලැබේ."),
        q("අම්බලන්ගොඩ සාම්ප්‍රදායික වෙස්මුහුණු කලාවේ ප්‍රධාන ප්‍රභේද තුන ලෙස සැලකෙන්නේ මොනවාද?", "කෝලම්, සන්නි සහ රක්ෂ වෙස්මුහුණු", "ග්‍රීක, රෝම සහ මිසර වෙස්මුහුණු", "බතික්, ලාක්ෂා සහ පිත්තල වෙස්මුහුණු", "ලිනෝ, කොලාජ් සහ මොසැයික් වෙස්මුහුණු", "නාට්‍ය සඳහා කෝලම්, රෝග සුව කිරීමේ ශාන්තිකර්ම සඳහා දහඅට සන්නිය හා අලංකරණයට රක්ෂ මුහුණු නිමවේ."),
        q("සම්ප්‍රදායික අම්බලන්ගොඩ වෙස්මුහුණු වර්ණ ගැන්වීමෙන් පසු දිලිසෙන ආරක්ෂිත පෙනුමක් දීමට පැරණි ශිල්පීන් ආලේප කළේ කුමක්ද?", "දොරණ තෙල් හා වලිත්තිය මිශ්‍රණය", "රසායනික ප්ලාස්ටික් වාර්නිෂ්", "මෝටර් රථ එන්ජින් තෙල්", "සීනි සහ ජලය දියරය", "දොරණ තෙල් මගින් වෙස්මුහුණේ වර්ණ කෘමීන්ගෙන් හා තෙතමනයෙන් ආරක්ෂා වී ස්වාභාවික ඔපයක් ලැබේ."),
        q("මැටි කර්මාන්තයේදී අත්ල මත මැටි බෝලයක් තබා මාපටැඟිල්ලෙන් මැද සිදුර තද කර කුඩා බඳුනක් සාදන මූලික ක්‍රමය කුමක්ද?", "ඇඟිලි තෙරපුම් ක්‍රමය (Pinch Pot)", "සකපෝරු ක්‍රමය (Wheel Throwing)", "මැටි ලෑලි ක්‍රමය (Slab Building)", "දියර අච්චු ක්‍රමය (Slip Casting)", "පාසල් කලා පන්තියේදී මූලික මැටි හැසිරවීම හුරු කිරීමට සරලම ක්‍රමය ඇඟිලි තෙරපුම් ක්‍රමයයි."),
        q("දිගු මැටි තීරු හෙවත් නූල් ආකාරයෙන් අඹරා එක මත එක තබා උස මැටි බඳුනක් ගොඩනගන ශිල්පීය ක්‍රමය කුමක්ද?", "මැටි දඟර ක්‍රමය (Coil Method)", "මැටි පතුරු ක්‍රමය (Slab Method)", "කැටයම් ක්‍රමය (Carving Method)", "ප්ලාස්ටර් ක්‍රමය (Plaster Method)", "එකිනෙකට සම්බන්ධ කරන දඟර අතර වාතය නොරැඳෙන සේ ඇතුළතින් හොඳින් මට්ටම් කිරීම වැදගත් වේ."),
        q("රෝලිං පින් එකකින් මැටි පැතලි ලෑලි මෙන් තුනී කර කපා ජ්‍යාමිතික හතරැස් පෙට්ටියක් හෝ බඳුනක් සෑදීමේ ක්‍රමය කුමක්ද?", "මැටි පතුරු ක්‍රමය (Slab Method)", "ඇඟිලි තෙරපුම් ක්‍රමය (Pinch Pot)", "දඟර ක්‍රමය (Coil Method)", "වියළි ඉසින ක්‍රමය (Airbrush)", "සමාන ඝනකමකින් යුත් මැටි ලෑලි කපා මඳක් වියළුණු පසු 'ස්ලිප් හා ස්කෝර්' ක්‍රමයෙන් අලවනු ලැබේ."),
        q("වේගයෙන් කැරකෙන තැටියක් මත මැටි ගුළිය තබා දෑතින් සමමිතික වටකුරු බඳුන් සෑදීමේ සාම්ප්‍රදායික ක්‍රමය කුමක්ද?", "සකපෝරු ක්‍රමය (Potter's Wheel)", "ලිනෝ මුද්‍රණ ක්‍රමය (Linocut)", "නියපොතු ලාක්ෂා ක්‍රමය (Lacquer)", "කොලාජ් ඇලවුම් ක්‍රමය (Collage)", "සකපෝරුව මත මැටි පිඬ හරි මැදට ගැනීම (Centering) නිවැරදි බඳුනක් සෑදීමේ පළමු පියවරයි."),
        q("බඳුනක් සෑදීමට පෙර අමු මැටි හොඳින් අනා තැළීම (Wedging / Kneading) සිදු කිරීමේ ප්‍රධානතම අරමුණ කුමක්ද?", "මැටි තුළ සිර වූ වායු බුබුළු ඉවත් කිරීම", "මැටිවල වර්ණය නිල් පැහැයට හැරවීම", "මැටි සම්පූර්ණයෙන් වතුරේ දිය කිරීම", "මැටිවලට ලෝහ කැබලි මිශ්‍ර කිරීම", "මැටි ඇතුළේ වායු බුබුළු ඉතිරි වුවහොත් පෝරණුවේ පිළිස්සීමේදී වාතය ප්‍රසාරණය වී බඳුන පුපුරා යයි."),
        q("මැටි බඳුනක් සෑදූ පසු සම්පූර්ණයෙන් වියළීමට පෙර, හැඩය නොබිඳී කැටයම් කැපීමට හා අත ඇලවීමට සුදුසුම තත්ත්වය කුමක්ද?", "සම් තද අවස්ථාව (Leather-hard)", "අමු දියර අවස්ථාව (Slip stage)", "ඇට වියළි අවස්ථාව (Bone-dry)", "ග්ලේස් පිළිස්සූ අවස්ථාව (Glazed)", "හොඳින් ඔප දැමීමට හා සියුම් කැටයම් කිරීමට වඩාත්ම සුදුසු තත්ත්වය 'ලෙදර්-හාඩ්' අවස්ථාවයි."),
        q("වියළි සියුම් මැටි භාණ්ඩයක් පෝරණුවට දැමීමට පෙර තෙතමනය සම්පූර්ණයෙන් නොමැති ඉතා බිඳෙනසුලු අවස්ථාව හඳුන්වන්නේ කෙසේද?", "ඇට වියළි අවස්ථාව (Bone-dry / Greenware)", "සම් තද අවස්ථාව (Leather-hard)", "බිස්ක් පිළිස්සූ අවස්ථාව (Bisqueware)", "උණු කළ වීදුරු අවස්ථාව (Glaze)", "තෙතමනය ඉතිරිව තිබියදී පෝරණුවට දැමුවහොත් හුමාලය නිසා මැටි බඳුන පුපුරා යන බැවින් සම්පූර්ණයෙන් වියළිය යුතුය."),
        q("පහත් උෂ්ණත්වයක පිළිස්සූ රතු-දුඹුරු සවිවර 'ටෙරාකොටා' හා අධික උෂ්ණත්වයේ පිළිස්සූ සුදු 'පෝසිලේන්' අතර වෙනස කුමක්ද?", "පෝසිලේන් සිදුරු රහිත, සිනිඳු හා ජලය උරා නොගන්නා සුදු මැටි වේ", "ටෙරාකොටා සැමවිටම විනිවිද පෙනෙන නිල් පැහැයක් ගනී", "පෝසිලේන් පෝරණුවේ නොපිලිස්සා අව්වේ වේලනු ලැබේ", "ටෙරාකොටා යනු ලෝහ කැබලි උණු කර සාදන ද්‍රව්‍යයකි", "වැඩි උෂ්ණත්වයක පිළිස්සීමේදී පෝසිලේන් හා ස්ටෝන්වෙයාර් ජලය කාන්දු නොවන සේ ඝන වේ."),
        q("මැටි හෝ ප්ලාස්ටර්වලින් විශාල මානව මූර්තියක් ගොඩනගන විට එය බරට කඩා නොවැටී රඳවා ගැනීමට ඇතුළතින් සාදන සැකිල්ල කුමක්ද?", "ආමචර් හෙවත් අභ්‍යන්තර කම්බි සැකිල්ල (Armature)", "පැලට් පුවරුව (Drawing Easel)", "සකපෝරු තැටිය (Wheel Head)", "මුද්‍රණ රාමුව (Printing Screen)", "ඇලුමිනියම් හෝ යකඩ කම්බි හා ලීවලින් සාදන සැකිල්ල මූර්තියට ශක්තිමත් අස්ථි පද්ධතියක් මෙන් ක්‍රියා කරයි."),
        q("සිදුරු සහිත සංකීර්ණ ලෝකඩ ප්‍රතිමා වාත්තු කිරීමේදී මී ඉටි ආකෘතියක් වටා මැටි ගා උණු කර ඉටි ඉවත් කර ලෝහ වත් කරන ක්‍රමය කුමක්ද?", "ඉටි දිය කිරීමේ වාත්තු ක්‍රමය (Lost-wax Casting)", "සකපෝරු ක්‍රමය (Wheel Throwing)", "ලිනෝ කැටයම් ක්‍රමය (Linocut)", "තෙත් බදාම ක්‍රමය (Buon Fresco)", "ශ්‍රී ලංකාවේ පොළොන්නරු යුගයේ ශිව නටරාජ ප්‍රතිමා පවා නිපදවූයේ මෙම ඉපැරණි වාත්තු ශිල්පයෙනි."),
        q("දැව කැටයම් කිරීමේදී (Wood Carving) ලීය පැළී කැඩී යාම වැළැක්වීමට කැටයම් නියන මෙහෙයවිය යුත්තේ කුමන අතටද?", "දැවයේ නහර හෙවත් කෙඳි දිශාවට (With the grain)", "කෙඳි දිශාවට සම්පූර්ණයෙන්ම විරුද්ධව හරහට", "සැමවිටම තමන්ගේම සිරුර දෙසට කපමින්", "දැවය ගින්නෙන් රත් කර අඟුරු වූ පසු", "කෙඳි දිශාව අනුව කැපීමෙන් සිනිඳු නිමාවක් ලැබෙන අතර කැටයම් කටුව සිරුරෙන් ඉවතට හැසිරවීම ආරක්ෂිත වේ."),
        q("මැටි පෝරණුවක් (Kiln) පිළිස්සී අවසන් වූ වහාම උණුසුම්ව තිබියදී දොර විවෘත නොකර සෙමින් නිවෙන්නට හරින්නේ ඇයි?", "ක්ෂණික උෂ්ණත්ව වෙනස (Thermal Shock) නිසා බඳුන් පිපිරීම වැළැක්වීමට", "මැටි බඳුන් ඉබේම දිය සායම් බවට හැරීම වැළැක්වීමට", "ඇතුළත ඇති බඳුන් සුළඟේ පියාඹා යාම වැළැක්වීමට", "සියලුම බඳුන් රන් පැහැයට හැරවීමට", "උණුසුම් භාණ්ඩ මත සිසිල් වාතය එක්වරම වැදීමෙන් ග්ලේස් ස්තරය හා මැටි බඳුන පුපුරා යා හැකිය."),
        q("බතික් නිර්මාණයක උණුසුම් ඉටි ආලේප කළ රෙද්ද වියළී තද වූ පසු අතින් පොඩි කර සායම් පෙඟවීමෙන් ලැබෙන අලංකාර ප්‍රතිඵලය කුමක්ද?", "සියුම් ඉරි වැටුණු නහර රටා (Crackle effect)", "සම්පූර්ණයෙන්ම හිස් සුදු රෙද්දක්", "ඝන ලෝහමය තහඩුවක්", "හතරැස් කොටු මෝස්තර පමණක්", "ඉටි පුපුරා ගිය සියුම් පැළුම් තුළින් ඩයි වර්ණ ඇතුළු වී බතික් කලාවට අනන්‍ය නහර රටා මැවේ."),
        q("බතික් නිර්මාණයේදී වර්ණ ගැන්වීම සම්පූර්ණ වූ පසු රෙද්දෙන් ඉටි සම්පූර්ණයෙන්ම ඉවත් කරන්නේ කෙසේද?", "උතුරන ජලයේ තම්බා හෝ පත්තර කොළ අතර තබා ඉස්තිරික්ක කිරීමෙන්", "ශීතකරණයක දින තුනක් තබා අයිස් කිරීමෙන්", "වැලි කඩදාසියකින් තදින් සූරා දැමීමෙන්", "තෙල් සායම් බුරුසුවකින් තීන්ත ගෑමෙන්", "උණු ජලයට සෝඩා අළු හා සබන් ස්වල්පයක් එක් කර තැම්බීමෙන් ඉටි දිය වී ඉවත් වේ."),
        q("ටයි-ඩයි (Tie-Dye) හෙවත් ගැට ගසා වර්ණ ගැන්වීමේදී රෙද්දේ මැදින් අල්ලා කරකවා රවුම් රබර් පටි දමා සාදන ජනප්‍රිය රටාව කුමක්ද?", "සර්පිලාකාර රටාව (Spiral / Swirl Pattern)", "සෘජු කොටු බැම්ම (Brick Pattern)", "කැඩපත් ලියවැල (Mirror Vine)", "මකර තොරණ (Makara Torana)", "රෙද්ද මැදින් ගෑරුප්පුවකින් හෝ ඇඟිලිවලින් කරකවා රවුමට බැඳ ඩයි යෙදීමෙන් වර්ණවත් සර්පිලාකාර රටාව සෑදේ."),
        q("තනි හතරැස් කඩදාසියක් නමා ජ්‍යාමිතික රටා හා සතුන්ගේ රූප කපා දිගහරින විට සමමිතික ලස්සන මෝස්තර ලබා ගන්නා ශිල්පය කුමක්ද?", "කිරිගාමි / කඩදාසි කැපුම් කලාව", "ඉකෙබානා මල් සැකසුම් කලාව", "මොසැයික් ගල් ඇලවුම් කලාව", "සකපෝරු මැටි කලාව", "පාසල් අලංකරණ, තොරණ හා වෙසක් කූඩු සැරසිලිවලදී මෙම සමමිතික කඩදාසි කැපුම් ක්‍රමය බහුලව යෙදේ."),
        q("සම්ප්‍රදායික පදික වේදිකාවක තැබූ තනි ප්‍රතිමාවකට වඩා නූතන 'ස්ථාපන කලාව' (Installation Art) වෙනස් වන්නේ කෙසේද?", "මුළු කාමරය හෝ පරිසර අවකාශයම කෘතියේ කොටසක් වීම", "සැමවිටම කුඩා මුද්දර ප්‍රමාණයෙන් නිමවා තිබීම", "පැන්සලෙන් පමණක් කඩදාසියේ ඇඳ තිබීම", "මිසර රජවරුන් පමණක් නිරූපණය කිරීම", "නරඹන්නාට කෘතිය ඉදිරිපිට සිට නොව කෘතිය ඇතුළත ඇවිද යමින් අත්දැකීම ලැබීමට ඉඩ සැලසේ."),
        q("පරිගණක ග්‍රැෆික් නිර්මාණයේදී 'රාස්ටර්' (Raster) ඡායාරූප විශාල කරන විට පික්සල් කොටු බොඳ වන අතර නොබිඳී පැහැදිලිව විශාල වන්නේ මොනවාද?", "වෙක්ටර් ග්‍රැෆික් (Vector Graphics)", "බිට්මැප් තිත් රූප (Bitmap Graphics)", "පැරණි JPEG ඡායාරූප", "අතින් ඇඳි ස්කෑන් පින්තූර", "ගණිතමය රේඛා හා වක්‍ර සමීකරණ මගින් ගොඩනැගෙන වෙක්ටර් රූප ලාංඡන නිර්මාණයට ඉතා සුදුසුය."),
        q("මුද්‍රණ කටයුතු (Posters / Books) සඳහා ඩිජිටල් චිත්‍රයක් සකසන විට තියුණු බව රැක ගැනීමට නිර්දේශිත විභේදනය (Resolution) කුමක්ද?", "අඟලකට තිත් 300 (300 DPI)", "අඟලකට තිත් 10 (10 DPI)", "අඟලකට තිත් 72 (72 DPI)", "අඟලකට තිත් 1 (1 DPI)", "පරිගණක තිර සඳහා 72 PPI ප්‍රමාණවත් වුවද, උසස් තත්ත්වයේ මුද්‍රණයක් සඳහා 300 DPI අවශ්‍ය වේ."),
        q("කලා සිසුවෙකු සිය වසරක නිර්මාණ එකතුව පිළිවෙළට හා ආරක්ෂිතව සංවිධානය කර තබා ගන්නා ගොනුව හඳුන්වන්නේ කුමන නමින්ද?", "කලා ගොනුව / පෝට්ෆෝලියෝ (Art Portfolio)", "ලිනෝ මුද්‍රණ පුවරුව (Printing Block)", "ස්කෙච් කැන්වසය (Canvas Frame)", "වර්ණ පැලට්ටුව (Color Palette)", "නිර්මාණ අතර තෙල් සායම් හෝ පැස්ටල් තැවරීම වැළැක්වීමට මැදින් ටිෂූ හෝ බටර් කඩදාසි තබා ගොනු කෙරේ."),
        q("රාමු කළ ජල සායම් චිත්‍රයක් වටා වීදුරුව හා චිත්‍රය එකිනෙක ගැටීම වැළැක්වීමට යොදන ඝන කාඩ්බෝඩ් මායිම කුමක්ද?", "මැට් පුවරුව (Mat Board / Mount)", "බ්ලෙන්ඩින් ස්ටම්ප් (Blending Stump)", "බ්‍රේයර් රෝලරය (Brayer)", "ග්ලේස් තහඩුව (Glaze Sheet)", "තෙතමනය නිසා චිත්‍රය වීදුරුවේ ඇලී විනාශ වීම වළක්වන අතර නිර්මාණයට ආකර්ෂණීය රාමු ගැඹුරක්ද දෙයි."),
        q("කලා විචාරයේදී 'සන්දර්භීය ප්‍රවේශය' (Contextual Criticism) මගින් කලා කෘතියක් අගය කරන විට ප්‍රධානව සොයා බලන්නේ කුමක්ද?", "කෘතිය බිහිවූ යුගයේ ඉතිහාසය, ආගම හා සමාජ පසුබිම", "කැන්වසයේ රෙදි වර්ගයේ මිල ගණන් පමණක්", "කලාකරුවා පැළඳ සිටි ඇඳුමේ පැහැය", "චිත්‍ර රාමුවේ බර හා ඝනකම", "උදාහරණයක් ලෙස ගර්නිකා හෝ මහනුවර බිතුසිතුවම් තේරුම් ගැනීමට එම සමාජ-ඓතිහාසික වටපිටාව ඉතා වැදගත් වේ."),
        q("කලා විචාරයේදී කෘතියක් සමාජ වෙනසක්, දේශපාලන පණිවිඩයක් හෝ සදාචාරාත්මක අරමුණක් ඉටු කරයිද යන්න මත අගයන න්‍යාය කුමක්ද?", "උපයෝගීතාවාදී / ප්‍රයෝජනවාදී විචාරය (Instrumentalism)", "ශුද්ධ ආකෘතිවාදය (Pure Formalism)", "වර්ණ විභේදනවාදය (Divisionism)", "අභිනය රේඛා විචාරය (Gesture Critique)", "කලා කෘතියක් මගින් ප්‍රේක්ෂක සමාජයට සිදු කරන බලපෑම හා පණිවිඩය මෙම විචාර ක්‍රමයෙන් පරීක්ෂා කෙරේ."),
        q("කලා විචාරයේ පළමු පියවර වන 'විස්තර කිරීමේදී' (Description) සහ අවසන් 'ඇගයීමේදී' (Judgement) ප්‍රකාශ අතර වෙනස කුමක්ද?", "විස්තර කිරීම ඇසට පෙනෙන කරුණු වන අතර ඇගයීම හේතු දක්වන මතයකි", "විස්තර කිරීමේදී කිසිදු කරුණක් නොකියා අනුමාන පමණක් කියයි", "ඇගයීම යනු කලා කෘතියේ මිල පමණක් තීරණය කිරීමයි", "දෙකෙන්ම අදහස් කරන්නේ කලාකරුවාගේ උපන් දිනය පමණි", "'චිත්‍රයේ රතු පැහැ ගසක් ඇත' යන්න විස්තරයක් වන අතර 'එම වර්ණ සංයෝජනය ප්‍රබලය' යන්න ඇගයීමකි."),
        q("සීගිරි බිතුසිතුවම් හා ඉන්දියාවේ අජන්තා බිතුසිතුවම් එකට තබා සමානකම් හා වෙනස්කම් පරීක්ෂා කිරීමේ විචාර ක්‍රමය කුමක්ද?", "සංසන්දනාත්මක විචාරය (Compare and Contrast)", "හුදෙක් පෞද්ගලික අනුමානය (Guesswork)", "මිල ගණන් විගණනය (Price Audit)", "ප්‍රාථමික වර්ණ ගණනය (Hue Counting)", "යුග දෙකක් හෝ කලාකරුවන් දෙදෙනෙකු අතර තාක්ෂණික හා ශෛලිමය ආභාස හඳුනා ගැනීමට මෙය ඉතා ප්‍රයෝජනවත්ය."),
        q("කලා කෘතියක් ඇගයීමේදී 'ශිල්පීය නිමාව' (Craftsmanship) යන නිර්ණායකයෙන් පරීක්ෂා කරනු ලබන්නේ කුමක්ද?", "කලාකරුවා මාධ්‍යය, උපකරණ හා ශිල්ප ක්‍රම හැසිරවූ නිපුණතාව", "චිත්‍රය අඳින ලද කාමරයේ පළල හා උස", "පින්තූරය අලෙවි වූ වෙන්දේසි මිල", "කලාකරුවාගේ පවුලේ සාමාජිකයන් ගණන", "නිර්මාණයේ පිරිසිදු බව, මැටි පිළිස්සීමේ නිවැරදි බව හෝ පින්සල් පාලනය ශිල්පීය නිමාවට අයත් වේ."),
        q("පාසල් හෝ වෘත්තීය කලා කෘතියක 'මුල් නිර්මාණශීලීත්වය' (Originality) අගයන්නේ කුමන ලක්ෂණය මතද?", "වෙනත් කෘති අනුකරණය නොකර නව්‍ය දෘෂ්ටියක් ඉදිරිපත් කිරීම", "පොතක ඇති ඡායාරූපයක් කාබන් කොළයකින් පිටපත් කිරීම", "වෙළඳපොළෙන් මිලදී ගත් ස්ටිකර් පමණක් ඇලවීම", "පෙර සිසුවෙකුගේ කෘතියක් නම වෙනස් කර ඉදිරිපත් කිරීම", "තමාගේම පරිකල්පනය, නිරීක්ෂණය හා සංවේදී අත්දැකීම් අලුත් ආකාරයකින් ඉදිරිපත් කිරීම කලාවේ හදවතයි."),
        q("කෞතුකාගාරයක හෝ කලාගාරයක චිත්‍ර හා මූර්ති නරඹන විට අනුගමනය කළ යුතු ප්‍රධාන ආචාර ධර්ම මොනවාද?", "කෘති ස්පර්ශ නොකිරීම හා ෆ්ලෑෂ් ඡායාරූප නොගැනීම", "තීන්ත මතුපිට ඇඟිලිවලින් අතුල්ලා බැලීම", "ආහාර පාන කලා කෘති අසල තබා ගැනීම", "ප්‍රතිමා මත නැඟී ඡායාරූප ගැනීම", "අතේ ඇති තෙල් හා දහදිය මෙන්ම කැමරා ෆ්ලෑෂ් ආලෝකය පැරණි වර්ණකවලට හානි සිදු කරයි."),
        q("කඩදාසි මත ඇඳි වටිනා දිය සායම් හෝ රේඛා සිතුවම් කාලයත් සමඟ කහ පැහැ ගැන්වී දිරාපත් වීම වැළැක්වීමට භාවිත කළ යුත්තේ කුමක්ද?", "අම්ල-රහිත කඩදාසි හා ආරක්ෂිත රාමු (Acid-free Paper)", "තෙත් වූ බිත්තිවල කෙළින්ම ඇලවීම", "සෘජු හිරු එළියේ දිනපතා තැබීම", "සාමාන්‍ය පත්තර කොළවල ඔතා තැබීම", "පුවත්පත් කඩදාසිවල ඇති අම්ල ගතිය කලා කෘති කහ පැහැ ගන්වන බැවින් අම්ල-රහිත මැට් පුවරු භාවිත කෙරේ."),
        q("වැඩි වේලාවක් චිත්‍ර අඳින සිසුවෙකුට තම අතේ සෙවණැල්ල කඩදාසිය මත නොවැටීම සඳහා (දකුණත් අයෙකු නම්) ආලෝකය තිබිය යුත්තේ කුමන පැත්තෙන්ද?", "වම් පැත්තෙන් හා ඉදිරියෙන්", "දකුණු පැත්තේ පිටුපසින්", "හරියටම හිසට පහළින්", "කිසිදු ආලෝකයක් නොමැතිව", "ලියන හෝ අඳින අතට ප්‍රතිවිරුද්ධ පැත්තෙන් ආලෝකය පැමිණීමෙන් ඇඳීමේ පැහැදිලි බව රැකේ."),
        q("ඉවතලන ප්ලාස්ටික් බෝතල්, කාඩ්බෝඩ්, පරණ පුවත්පත් හා ලී කැබලි යොදාගෙන කලාත්මක ප්‍රතිමා හෝ සැරසිලි තැනීම හඳුන්වන්නේ කෙසේද?", "ප්‍රතිචක්‍රීකරණ කලාව (Recycled / Upcycled Art)", "තෙත් බදාම බිතුසිතුවම් (Buon Fresco)", "රන් කැටයම් කලාව (Gold Engraving)", "ශිලා ලේඛන කලාව (Lithic Epigraphy)", "පරිසර දූෂණය අවම කරමින් අපද්‍රව්‍යවලට නව කලාත්මක වටිනාකමක් දීම මෙම ප්‍රායෝගික ක්‍රමයේ අරමුණයි."),
        q("පාසල් චිත්‍ර කලා අධ්‍යාපනය තුළින් සිසුවෙකුගේ එදිනෙදා ජීවිතයට ලැබෙන 'සෞන්දර්ය සංවේදීතාව' (Aesthetic Sensitivity) යනු කුමක්ද?", "පිළිවෙළ, වර්ණ ගැළපුම හා පරිසර සුන්දරත්වය අගය කිරීමේ හැකියාව", "සෑම චිත්‍රයකම මිල ගණන් පමණක් ගණනය කිරීම", "වෙනත් කෙනෙකුගේ නිර්මාණ විවේචනය කර අවමන් කිරීම", "පන්ති කාමරය තීන්තවලින් අපිරිසිදු කිරීම", "ඇඳුම් පැළඳුම්, ගෙවතු අලංකරණය හා භාණ්ඩ තේරීමේදී රසඥතාවෙන් කටයුතු කිරීමට කලාව මග පෙන්වයි."),
        q("'කලා ඉතිහාසඥයා' (Art Historian) සහ 'කලා විචාරකයා' (Art Critic) අතර ඇති ප්‍රධාන වෘත්තීය වෙනස කුමක්ද?", "ඉතිහාසඥයා කාල පසුබිම සොයන අතර විචාරකයා ගුණාත්මක අගය විමසයි", "ඉතිහාසඥයා තීන්ත මිශ්‍ර කරන අතර විචාරකයා කැන්වස් වියයි", "විචාරකයා කෞතුකාගාර භාරව පමණක් වැඩ කරයි", "දෙදෙනාම සිදු කරන්නේ කලා කෘති වෙන්දේසි කිරීම පමණි", "කෘතියේ කාල වකවානු හා ශෛලි විකාශනය ඉතිහාසඥයා හදාරන අතර විචාරකයා එහි අර්ථය හා අගය විශ්ලේෂණය කරයි."),
        q("අ.පො.ස. (සා.පෙළ) චිත්‍ර කලා විභාගයේ සියලු කොටස් (ඉතිහාසය, සංයුතිය, මෝස්තර හා විචාරය) එකට අධ්‍යයනය කිරීමෙන් සිසුවා ලබන සමස්ත හැකියාව කුමක්ද?", "තාක්ෂණික දැනුම, නිර්මාණාත්මක ප්‍රකාශනය හා සංස්කෘතික රසවින්දනය", "මිනිස් රූප පමණක් කෝදුවෙන් ඇඳීමේ හැකියාව", "කළු සුදු වර්ණ පමණක් මිශ්‍ර කිරීමේ හැකියාව", "පැරණි ප්‍රතිමා පමණක් කටපාඩම් කිරීමේ හැකියාව", "සම්ප්‍රදාය හඳුනා ගනිමින් ස්වාධීනව සිතා නිර්මාණ බිහි කිරීමටත් කලාව තර්කානුකූලව අගය කිරීමටත් හැකි වේ.")
    )
}
